contracts/BondVesting.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.24;

struct VestingSchedule {
    uint256 amount;
    uint64 cliff;
    uint64 vesting;
    uint64 start;
}

/**
 * @title BondVesting
 * @author Michael Duchesne (michael.duchesne@t-rize.io)
 * @notice
 *
 * Tracks vesting of tokens using a linear unlock
 *
 * Tokens are fully vested until the cliff ends.
 * Tokens are unlocked linearly from the cliff until the end of the vesting period.
 * Tokens are fully unlocked past the vesting
 *
 * Tracks start, cliff and vesting with uint64 instead of uin256 (like block.timestamp), the sum is
 * way past any practical application
 */
contract BondVesting {
    mapping(uint256 => VestingSchedule) private _schedules;

    event VestingUpdated(
        uint256 indexed nftId,
        uint256 amount,
        uint64 cliff,
        uint64 vesting,
        uint64 start
    );

    error VestingAlreadyStarted(uint256 vestId);
    error VestingInvalidUpdate(uint256 value);

    /**
     * returns the amount of token which are not yet unlocked
     * @param tokenId the nft id
     */
    function vested(uint256 tokenId) public view returns (uint256) {
        VestingSchedule storage vest = _schedules[tokenId];
        /**
         * Small time manipulation is not critical as it will
         * frontrun only a small portion of tokens
         **/
        uint256 timestamp = block.timestamp; // solhint-disable-line not-rely-on-time
        if (vest.amount == 0) {
            return 0;
        }

        uint256 cliffEnd = vest.start + vest.cliff;
        if (timestamp <= cliffEnd) {
            return vest.amount;
        }

        uint256 vestingEnd = cliffEnd + vest.vesting;
        if (timestamp >= vestingEnd) {
            return 0;
        }

        uint256 vestingLeft = vestingEnd - timestamp;
        return (vestingLeft * vest.amount) / vest.vesting;
    }

    function getSchedule(
        uint256 tokenId
    ) public view returns (VestingSchedule memory) {
        return _schedules[tokenId];
    }

    /**
     * @dev start + cliff + vesting should not overflow a uint256
     * @param id The id for the vesting schedule
     * @param schedule cliff and vesting are lengths in seconds, start is a timestamp
     */
    function _startVesting(
        uint256 id,
        VestingSchedule memory schedule
    ) internal {
        if (_schedules[id].amount > 0) {
            revert VestingAlreadyStarted(id);
        }
        _schedules[id] = schedule;
        emit VestingUpdated(
            id,
            schedule.amount,
            schedule.cliff,
            schedule.vesting,
            schedule.start
        );
    }

    /**
     * update the vesting schedule of the vest. The terms can be shortened, but not increased
     * @param id the id of the vesting
     * @param schedule the new vesting schedule
     */
    function _updateVesting(
        uint256 id,
        VestingSchedule memory schedule
    ) internal {
        if (vested(id) < schedule.amount) {
            revert VestingInvalidUpdate(schedule.amount);
        }
        VestingSchedule storage previousSchedule = _schedules[id];
        if (schedule.start > previousSchedule.start) {
            revert VestingInvalidUpdate(schedule.start);
        }
        if (schedule.vesting > previousSchedule.vesting) {
            revert VestingInvalidUpdate(schedule.vesting);
        }
        if (schedule.cliff > previousSchedule.cliff) {
            revert VestingInvalidUpdate(schedule.cliff);
        }
        _schedules[id] = schedule;
        emit VestingUpdated(
            id,
            schedule.amount,
            schedule.cliff,
            schedule.vesting,
            schedule.start
        );
    }
}

contracts/configuration/AccessRestricted.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.24;

import {IAccessList} from "contracts/interfaces/IAccessList.sol";

abstract contract AccessRestricted {
    IAccessList private immutable _ACCESS_LIST;

    error SenderNotCommittee(address sender);
    error SenderNotBridge(address sender);

    modifier onlyCommittee() {
        if (_ACCESS_LIST.isCommittee(msg.sender) == false) {
            revert SenderNotCommittee(msg.sender);
        }
        _;
    }

    modifier onlyBridge() {
        if (_ACCESS_LIST.isBridge(msg.sender) == false) {
            revert SenderNotBridge(msg.sender);
        }
        _;
    }

    constructor(address accessList) {
        _ACCESS_LIST = IAccessList(accessList);
    }

    function getAccessList() public view virtual returns (address) {
        return address(_ACCESS_LIST);
    }
}

contracts/GovernanceBonding.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.24;

import {WeightedBonds, Pool} from "./WeightedBonds.sol";
import {AccessRestricted} from "contracts/configuration/AccessRestricted.sol";

contract GovernanceBonding is WeightedBonds, AccessRestricted {
    error IllegalWarmupRelease();

    constructor(
        address bondNft,
        address accessList
    ) WeightedBonds(bondNft) AccessRestricted(accessList) {}

    /**
     * @notice
     * Defines the time required between breaking the bond and calling the release function
     * Requires caller to be committee
     * @param warmup time in seconds
     */
    function setReleaseWarmup(uint256 warmup) public onlyCommittee {
        if (warmup > 31 days) {
            revert IllegalWarmupRelease();
        }
        _setReleaseWarmup(warmup);
    }

    /**
     * adds a pool
     * @param pool pool struct
     */
    function initPool(Pool memory pool) public onlyCommittee returns (uint16) {
        return _initPool(pool);
    }

    /**
     * @notice Update the parameters of a pool
     * Requires caller to be committee
     * @dev a pool can be disabled if you set `baseWeight` and `maturedBonusWeight` to 0
     * @param poolId id of the pool
     * @param baseWeight new value for base weight
     * @param maturedWeightBonus new value for bonus
     * @param fullMaturity new value for maturity
     */
    function updatePool(
        uint16 poolId,
        uint32 baseWeight,
        uint32 maturedWeightBonus,
        uint128 fullMaturity
    ) public onlyCommittee {
        _updatePool(poolId, baseWeight, maturedWeightBonus, fullMaturity);
    }

    function addMigrator(address migrator) public onlyCommittee {
        _addMigrator(migrator);
    }

    function removeMigrator(address migrator) public onlyCommittee {
        _removeMigrator(migrator);
    }
}

contracts/interfaces/IAccessList.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.24;

import { IAccessControl} from "@openzeppelin/contracts/access/IAccessControl.sol";

/**
 * @title RizeAccessList
 * @author michael.duchesne@t-rize.io
 * @notice 
 * 
 * Contains addresses of system contracts and roles
 * 
 */
interface IAccessList is IAccessControl {
  function setRoleAdmin(bytes32 role, bytes32 admin) external;
  function isCommittee(address addrezz) external view returns(bool);
  function isBridge(address addrezz) external view returns(bool);
  function getBonds() external view returns(address);
  function getToken() external view returns(address);
  function getGovernanceBonding() external view returns(address);
  function getTreasury() external view returns(address);
}

